/**
 * diagnosis-session-store.ts — 诊断会话持久化
 *
 * B2: 对标 Claw-Code session.rs + Hermes hermes_state.py。
 *
 * Claw-Code 模式：
 *   - JSONL 追加写（一条消息一行）→ 重启读小文件，快
 *   - 原子写入（temp file + rename）
 *   - 轮转（256KB，保留 3 份）
 *   - 密钥脱敏（写入前过滤敏感字段）
 *   - 字段截断（16KB 上限）
 *
 * Hermes 模式：
 *   - SQLite + WAL 模式 → 并发读
 *   - FTS5 全文搜索 → 快速检索历史消息
 *   - 会话元数据索引
 *
 * Synova 融合：
 *   - JSONL = 主持久化（对标 Claw-Code，重启快）
 *   - SQLite = 索引 + 搜索（对标 Hermes，检索快）
 *   - 会话分裂：压缩后创建子会话（对标 Hermes parent_session_id）
 */
export interface SessionMessage {
    role: 'system' | 'user' | 'assistant' | 'tool';
    content: string;
    phase?: number;
    toolName?: string;
    tokens?: number;
    timestamp: string;
}
export interface DiagnosisSession {
    sessionId: string;
    orgId: string;
    teamId: string;
    status: 'active' | 'compacted' | 'completed' | 'archived';
    messageCount: number;
    compactionCount: number;
    /** 压缩后创建的子会话 ID（对标 Hermes parent_session_id） */
    parentSessionId?: string;
    /** 子会话列表 */
    childSessionIds: string[];
    createdAt: string;
    updatedAt: string;
    /** 估算总 token 数 */
    estimatedTokens: number;
}
export interface SessionSearchResult {
    sessionId: string;
    messageContent: string;
    phase?: number;
    timestamp: string;
    score: number;
}
export declare function initSessionStore(dir: string, database?: any): void;
export declare function createSession(orgId: string, teamId: string): DiagnosisSession;
export declare function getSession(sessionId: string): DiagnosisSession | null;
export declare function appendMessage(sessionId: string, orgId: string, message: Omit<SessionMessage, 'timestamp'>): void;
export declare function compactSession(orgId: string, sessionId: string, compactionSummary: string): string;
export declare function searchSessions(orgId: string, query: string, limit?: number): SessionSearchResult[];
export declare function loadSessionMessages(orgId: string, sessionId: string): SessionMessage[];
/** 关闭存储（测试用） */
export declare function closeSessionStore(): void;
